def parse_roman(s):
    if not isinstance(s, str) or not s:
        return None

    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    for ch in s:
        if ch not in vals:
            return None

    total = 0
    n = len(s)
    i = 0
    while i < n:
        cur = vals[s[i]]
        if i + 1 < n:
            nxt = vals[s[i+1]]
            if cur < nxt:
                total += nxt - cur
                i += 2
                continue
        total += cur
        i += 1

    if total < 1 or total > 3999:
        return None

    def to_roman(num):
        vals_order = [
            (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
            (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
            (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'),
            (1, 'I')
        ]
        result = []
        for v, sym in vals_order:
            while num >= v:
                result.append(sym)
                num -= v
        return ''.join(result)

    canonical = to_roman(total)
    if canonical == s:
        return total
    return None

